# owner: platform
import unittest

from tests.support import data_file
from rosterkit.reader import read_roster
from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def make(last, first, section, email):
    ident = last + first
    return Student(ident, last, first, section, email)


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name_and_aligned(self):
        rows = contact_rows(
            [
                make("Young", "Al", "B", "al@x.org"),
                make("Abbott", "Bea", "AA", "bea@x.org")
            ]
        )
        self.assertEqual(
            rows,
            [
                "Abbott, Bea  AA  bea@x.org",
                "Young, Al    B   al@x.org"
            ]
        )

    def test_missing_email_names_the_student(self):
        roster = [
            make("Lopez", "Ana", "A", "ana@x.org"),
            make("Baker", "Cy", "A", None)
        ]
        with self.assertRaises(ValueError) as caught:
            contact_rows(roster)
        self.assertIn("Baker, Cy", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        with self.assertRaises(ValueError):
            contact_rows([make("Lopez", "Ana", "A", "")])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])

    def test_input_order_is_left_alone(self):
        roster = [
            make("Zed", "Al", "A", "z@x.org"),
            make("Ames", "Bo", "A", "a@x.org")
        ]
        contact_rows(roster)
        self.assertEqual(roster[0].last_name, "Zed")

    def test_roster_file_rows(self):
        students = read_roster(data_file("roster.csv"))
        withmail = [item for item in students if item.email]
        rows = contact_rows(withmail)
        self.assertEqual(len(rows), len(withmail))
